resource pageOnCall 'Microsoft.Insights/actionGroups@2023-01-01' = {
  name: 'ag-page-oncall'
  location: 'global'
  properties: {
    groupShortName: 'oncall'
    enabled: true
    emailReceivers: [ { name: 'oncall', emailAddress: 'oncall@example.com', useCommonAlertSchema: true } ]
    webhookReceivers: [ { name: 'pagerduty', serviceUri: pagerDutyUrl, useCommonAlertSchema: true } ]
  }
}

resource highErrorRate 'Microsoft.Insights/metricAlerts@2018-03-01' = {
  name: 'alert-api-5xx-rate'
  location: 'global'
  properties: {
    severity: 1
    enabled: true
    scopes: [ appInsights.id ]
    evaluationFrequency: 'PT1M'
    windowSize: 'PT5M'
    criteria: {
      allOf: [
        {
          criterionType: 'DynamicThresholdCriterion'
          metricName: 'requests/failed'
          operator: 'GreaterThan'
          alertSensitivity: 'Medium'
          failingPeriods: { numberOfEvaluationPeriods: 5, minFailingPeriodsToAlert: 3 }
        }
      ]
    }
    actions: [ { actionGroupId: pageOnCall.id } ]
  }
}
